vector<int> diffTree;
int n;

void pointUpdate(int i, int delta) {
    for (; i <= n; i += i & (-i)) diffTree[i] += delta;
}

void rangeUpdate(int l, int r, int delta) {
    pointUpdate(l, delta);
    pointUpdate(r + 1, -delta);
}

int pointQuery(int i) {
    int sum = 0;
    for (; i > 0; i -= i & (-i)) sum += diffTree[i];
    return sum; // this is arr[i] after all range updates applied
}
